const markGoogleExportDeleted = `-- name: MarkGoogleExportDeleted :exec
UPDATE google_exports
SET deleted = true, requested_at = $1::timestamptz, next_attempt_at = $1::timestamptz,
    state = CASE WHEN state = 'failed' THEN 'failed' ELSE 'pending' END, updated_at = now()
WHERE event_id = $2
`

type MarkGoogleExportDeletedParams struct {
	Now     pgtype.Timestamptz
	EventID pgtype.UUID
}

// The event was deleted in Life OS: its copy in Google is deleted next.
func (q *Queries) MarkGoogleExportDeleted(ctx context.Context, arg MarkGoogleExportDeletedParams) error {
	_, err := q.db.Exec(ctx, markGoogleExportDeleted, arg.Now, arg.EventID)
	return err
}

const markGoogleExportsDue = `-- name: MarkGoogleExportsDue :exec
UPDATE google_exports
SET next_attempt_at = $1::timestamptz, updated_at = now()
WHERE connection_id = $2 AND state <> 'synced'
`

type MarkGoogleExportsDueParams struct {
	Now          pgtype.Timestamptz
	ConnectionID pgtype.UUID
}

// Makes every waiting export due now (after reconnecting or switching
// export on).
func (q *Queries) MarkGoogleExportsDue(ctx context.Context, arg MarkGoogleExportsDueParams) error {
	_, err := q.db.Exec(ctx, markGoogleExportsDue, arg.Now, arg.ConnectionID)
	return err
}

const parkGoogleExport = `-- name: ParkGoogleExport :exec
UPDATE google_exports
SET exporting_until = NULL, next_attempt_at = $1::timestamptz, updated_at = now()
WHERE event_id = $2
`

type ParkGoogleExportParams struct {
	NextAttemptAt pgtype.Timestamptz
	EventID       pgtype.UUID
}

// Gives the lease up without an attempt (export switched off, Google not
// usable); next_attempt_at, when given, retries then.
func (q *Queries) ParkGoogleExport(ctx context.Context, arg ParkGoogleExportParams) error {
	_, err := q.db.Exec(ctx, parkGoogleExport, arg.NextAttemptAt, arg.EventID)
	return err
}

const resetGoogleExports = `-- name: ResetGoogleExports :exec
WITH dropped AS (
    DELETE FROM google_exports WHERE google_exports.connection_id = $2 AND deleted
)
UPDATE google_exports
SET google_calendar_id = NULL, google_event_id = NULL, etag = NULL, google_updated = NULL, exported_exceptions = '{}',
    state = 'pending', next_attempt_at = $1::timestamptz, requested_at = $1::timestamptz, updated_at = now()
WHERE google_exports.connection_id = $2 AND NOT deleted
`

type ResetGoogleExportsParams struct {
	Now          pgtype.Timestamptz
	ConnectionID pgtype.UUID
}

// The Life OS calendar was created anew: every exported event is written
// to it again, and deletions have nothing left to delete.
func (q *Queries) ResetGoogleExports(ctx context.Context, arg ResetGoogleExportsParams) error {
	_, err := q.db.Exec(ctx, resetGoogleExports, arg.Now, arg.ConnectionID)
	return err
}

